namespace RecipeCommunity.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    [MinLength(10, ErrorMessage = "Please provide at least 10 characters for ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    [MinLength(20, ErrorMessage = "Please provide at least 20 characters for steps.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day with these morning favorites", Icon = "🍳" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥪" },
            new() { Name = "Dinner", Description = "Hearty evening recipes for the whole family", Icon = "🍲" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Vegetarian", Description = "Delicious plant-based dishes", Icon = "🥗" },
            new() { Name = "Quick & Easy", Description = "Ready in 30 minutes or less", Icon = "⏱️" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nButter for cooking", Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a buttered pan over medium heat.\n5. Pour 1/4 cup batter per pancake.\n6. Flip when bubbles form on surface.\n7. Cook until golden brown.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Grilled Cheese Sandwich", Category = "Lunch", Ingredients = "2 slices bread\n2 slices cheddar cheese\n1 tbsp butter", Steps = "1. Butter one side of each bread slice.\n2. Place one slice butter-side down in a pan.\n3. Add cheese slices.\n4. Top with second bread slice, butter-side up.\n5. Cook on medium heat until golden.\n6. Flip and cook other side until cheese melts.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 cloves garlic\n400g canned tomatoes\n2 tbsp tomato paste\nOlive oil\nSalt and pepper\nFresh basil", Steps = "1. Cook spaghetti according to package directions.\n2. Heat olive oil and sauté onion until soft.\n3. Add garlic and cook 1 minute.\n4. Add ground beef and brown thoroughly.\n5. Stir in tomatoes and tomato paste.\n6. Simmer for 20 minutes.\n7. Season with salt and pepper.\n8. Serve over spaghetti with fresh basil.", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "2.25 cups flour\n1 cup butter, softened\n3/4 cup sugar\n3/4 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips", Steps = "1. Preheat oven to 375°F (190°C).\n2. Cream butter and sugars together.\n3. Beat in eggs and vanilla.\n4. Mix in flour and baking soda.\n5. Fold in chocolate chips.\n6. Drop spoonfuls onto baking sheet.\n7. Bake 9-11 minutes until golden.\n8. Cool on baking sheet for 2 minutes.", AverageRating = 4.9, RatingCount = 31 },
            new() { Id = 5, Title = "Mediterranean Quinoa Bowl", Category = "Vegetarian", Ingredients = "1 cup quinoa\n1 cucumber, diced\n1 cup cherry tomatoes\n1/2 red onion\n1/2 cup kalamata olives\n1/2 cup feta cheese\nOlive oil\nLemon juice\nFresh herbs", Steps = "1. Cook quinoa according to package directions.\n2. Let quinoa cool to room temperature.\n3. Dice cucumber, tomatoes, and onion.\n4. Combine quinoa with vegetables.\n5. Add olives and crumbled feta.\n6. Dress with olive oil and lemon juice.\n7. Toss with fresh herbs and serve.", AverageRating = 4.3, RatingCount = 15 },
            new() { Id = 6, Title = "15-Minute Stir Fry", Category = "Quick & Easy", Ingredients = "2 chicken breasts, sliced\n2 cups mixed vegetables\n3 tbsp soy sauce\n1 tbsp sesame oil\n1 tsp ginger\n2 cloves garlic\nRice for serving", Steps = "1. Heat sesame oil in a wok over high heat.\n2. Cook chicken until browned (5 min).\n3. Add garlic and ginger, stir 30 seconds.\n4. Add vegetables and stir-fry 3-4 minutes.\n5. Pour in soy sauce and toss.\n6. Serve immediately over rice.", AverageRating = 4.1, RatingCount = 19 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var totalSum = (recipe.AverageRating * recipe.RatingCount) + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(totalSum / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

