@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="d-inline-block">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="@(i <= SelectedRating ? "text-warning" : "text-muted")"
                  style="cursor: pointer;"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => HoverRating = star"
                  @onmouseout="() => HoverRating = 0">
                @(i <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "★" : "☆")
            </span>
        }
    </span>
    <small class="text-muted ms-2">
        @if (HasRated)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        @CurrentRating/5 (@RatingCount ratings)
    </small>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating { get; set; }
    private int HoverRating { get; set; }
    private bool HasRated { get; set; }

    protected override void OnParametersSet()
    {
        SelectedRating = (int)Math.Round(CurrentRating);
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        HasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe != null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

