            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@Submission.Title</strong>" has been added to the community.</p>
            <a href="/category/@Uri.EscapeDataString(Submission.Category)" class="btn btn-primary">View in @Submission.Category</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="alert alert-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => Submission.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Submission.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Submission.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => Submission.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps" placeholder="Describe each step..." />
                <ValidationMessage For="() => Submission.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission Submission { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        RecipeService.SubmitRecipe(Submission);
        IsSubmitted = true;
    }

    private void Reset()
    {
        Submission = new RecipeSubmission();
        IsSubmitted = false;
    }
}

